INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('bearnard', 265533, '2024-08-12', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7umu.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2ig6.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bearnard', '"Bearnard" is a captivating single-player adventure game where you step into the furry paws of Bearnard, a valiant archer-bear on a mission to reclaim a legendary bow and protect his beloved forest from threats. This journey takes players through diverse biomes, including dense forests, dark mines, snowy mountains, abandoned castles, and mysterious dungeons, each presenting unique challenges and enemies.
