INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Decline''s Drops', 'Grab your punching gloves, put your clogs on and smash your way in the world of Decline''s Drops, a fully hand-drawn platform-brawler full of weird frogs, bizarre chickens and odd hydras! Avenge your destroyed garden and defeat the 6 heads of the Eternal Corp.! If you can, that is.' FROM games WHERE igdb_id = 177278 ON CONFLICT (game_id, language_code) DO NOTHING;
