INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Chrysalis', 'Defend your Chrysalis from growing hordes of monsters in this hybrid game that combines elements of tower defense, survival, and roguelike RPGs. Explore procedurally generated levels, possess and control animals, and grow deadly gardens. How far can you get before the next wave of monsters attacks?
