INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Apollo Justice: Ace Attorney', 'Apollo Justice is the first game in the series that does not feature Phoenix Wright as the main protagonist, though it is not the first time a different attorney has been playable. The game is set in the year 2026, which is seven years after Phoenix Wright: Ace Attorney Trials and Tribulations. Phoenix Wright has been stripped of his attorney''s badge, and Apollo Justice, an up-and-coming attorney, becomes his apprentice.' FROM games WHERE igdb_id = 253010 ON CONFLICT (game_id, language_code) DO NOTHING;
