INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Awaria', 'Welcome to the tunnel maintenance crew. If the generators fail, it''s your job to fix them. Check what''s wrong, craft all the needed parts and deliver them. It''s simple. Just stay clear of anything that randomly cracks bolts of electricity, spews fire, throws sharp pieces of scrap at high-velocity or radiates with ominous green light.' FROM games WHERE igdb_id = 321629 ON CONFLICT (game_id, language_code) DO NOTHING;
