INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stickin'' the Landing', 'Stickin’ the Landing is a relaxing puzzle game where you pilot a spaceship around outlandish galaxies, using stickers and their gravitational properties to reach your destination. Embark on an odyssey through the home’s nooks and crannies, and discover everything this marvelous world has to offer!' FROM games WHERE igdb_id = 283355 ON CONFLICT (game_id, language_code) DO NOTHING;
