INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Robobeat', 'Keep your trigger finger on the pulse! In rhythm shooter Robobeat, it’s all about maximising your damage by shooting to the beat. Wall run, grapple hook, slide, and bunny hop your way through the haphazard mansion of a crazed robot-showman.' FROM games WHERE igdb_id = 192534 ON CONFLICT (game_id, language_code) DO NOTHING;
