INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('the-good-people-na-daoine-maithe', 212138, '2024-11-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa1eb.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1rw3.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Good People: Na Daoine Maithe', 'The Good People (Na Daoine Maithe) is a lore-rich and choice-driven historical fantasy visual novel inspired by Irish mythology and Celtic folklore. Play as a tenant farmer from mid-19th century Ireland, whose path becomes inexplicably entwined in fairy affairs after getting robbed by the roadside and lured into the mythic and war-torn world of Tír na nÓg: A once unified land, now divided into the Seelie and Unseelie Courts. Will you escape and return home with your stolen belongings? Or does fate have something else in mind?' FROM games WHERE igdb_id = 212138 ON CONFLICT (game_id, language_code) DO NOTHING;
