INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Albatroz', 'Leave your dull urban life behind and set out on a journey to find your lost brother, who disappeared while looking to reach a mythical mountain called Albatroz. Use your survival skills to traverse beautiful yet challenging landscapes, ranging from scorching coastal regions to freezing mountains. Manage your resources, strengthen your body, and improve your abilities as you face the wilderness head-on. Discover yourself as you find that the journey might actually be just as important as the destination.' FROM games WHERE igdb_id = 255084 ON CONFLICT (game_id, language_code) DO NOTHING;
