INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Grunn', 'A gardener gets hired to do some maintenance work over the weekend. The tall grass needs to be cut, the wild hedges trimmed, and the dead flowers could use some water. A simple task, but strangely some tools are missing…The owner of the garden isn''t around, and their house is off-limits. Perhaps new tools can be found in the mysterious town, or maybe some of the reserved townsfolk have seen them?' FROM games WHERE igdb_id = 281353 ON CONFLICT (game_id, language_code) DO NOTHING;
