INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ruthnar Online', 'Ruthnar Online is a free sandbox 2D MMORPG where you can face powerful creatures to develop your character in an open medieval fantasy world and craft your own equipment with eight diferent professions. The game also features guild wars and four different factions, join one of them to defend it and raid enemy cities. Finally, when you get strong enough you''ll be able to fight in the BattleGrounds: Stronghold Conquests, Combat Arenas, Survival/Battle Royale, Leagues, Tournaments and more.' FROM games WHERE igdb_id = 293325 ON CONFLICT (game_id, language_code) DO NOTHING;
