INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Breathless Winds', 'After recovering from a painful incident, a closeted trans woman finds herself split between four possible paths - returning to sailing, becoming a healer, helping the resident witch, or joining a prince on a mysterious quest. A fantasy romance visual novel about love and self-discovery.' FROM games WHERE igdb_id = 237159 ON CONFLICT (game_id, language_code) DO NOTHING;
