INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MiSide', 'MiSide is an adventure game with horror elements, telling the story of a simple guy who, for mystical reasons, finds himself in a mobile simulation. Appearing in the house he has just observed on his smartphone screen, the hero becomes confused. The stunned guy follows the instructions of a certain device he discovered in the bedroom. A few moments later, he is greeted by a pretty girl, whose image is also familiar to the young man from this mobile game.' FROM games WHERE igdb_id = 255777 ON CONFLICT (game_id, language_code) DO NOTHING;
