INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Keylocker: Turn Based Cyberpunk Action', 'Keylocker is a Cyberpunk turn based rhythm JRPG inspired by the Mario&Luigi RPG series and Chrono Trigger, in which you play as the singer and songwriter, BOBO. Fuel your moves with the electric power of music in this unforgiving planet by using real-time execution of moves in rhythm game style! Battle the authorities, unlock the secrets of Saturn, play on your own bands'' concerts and hack into the network to bring an end to this corrupt system, for better or worse.' FROM games WHERE igdb_id = 118450 ON CONFLICT (game_id, language_code) DO NOTHING;
