INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tiny Glade', 'Tiny Glade is a small relaxing game about doodling castles. Explore gridless building chemistry, and watch the game carefully assemble every brick, pebble and plank. There''s no management, combat, or wrong answers - just kick back and turn forgotten meadows into lovable dioramas.' FROM games WHERE igdb_id = 228516 ON CONFLICT (game_id, language_code) DO NOTHING;
