INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '1000xResist', '1000xRESIST is a thrilling sci-fi adventure. The year is unknown, and a disease spread by an alien invasion keeps you underground. You are Watcher. You dutifully fulfil your purpose in serving the ALLMOTHER, until the day you discover a shocking secret that changes everything. The game blends visual novel, walking simulator, and third-person exploration as you navigate nonlinear memories and unravel the mystery of what really happened—and what’s still being kept from you.' FROM games WHERE igdb_id = 218282 ON CONFLICT (game_id, language_code) DO NOTHING;
