INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Foundry', 'Foundry is a first-person base building game set in an endless procedurally generated voxel world. It places heavy focus on automation, conveyor belts & logistics management. The main goal is to automate the production of complex items to conduct research and unlock more effective and advanced technology. The game supports single- & cooperative multiplayer.' FROM games WHERE igdb_id = 139150 ON CONFLICT (game_id, language_code) DO NOTHING;
