INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MLB The Show 24', 'Swing for the fences, experience game-deciding moments, become a legend and live out your baseball dreams in MLB The Show 24. Earn your call up from the minors to the big leagues and prove you’ve got what it takes at the top. Learn about known and unsung legends of the sport and take inspiration from their heroics. Hold your nerve when it matters and earn the right to be called World Series champions.' FROM games WHERE igdb_id = 282900 ON CONFLICT (game_id, language_code) DO NOTHING;
