INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dead Rising Deluxe Remaster', 'Dead Rising returns with modern graphics! More than just a remaster, this Deluxe Remaster is a full graphical overhaul of the first game in zombie-slaughtering action game series "Dead Rising." This remaster has also been fully voiced, supports auto-saves, and has various other quality-of-life features. Witness the unmatched mayhem and freedom for yourself!' FROM games WHERE igdb_id = 306979 ON CONFLICT (game_id, language_code) DO NOTHING;
