INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rise of the Ronin', 'Rise of the Rōnin is a combat focused open-world action RPG that takes place in Japan at a time of great change. It is the very end of a 300-year long Edo Period, commonly known as “Bakumatsu”. Set in the late 19th century, Japan is facing the darkest of times as it struggles with its oppressive rulers and deadly diseases while western influence permeates as civil war continues to rage between the Tokugawa Shogunate and the Anti-Shogunate factions.' FROM games WHERE igdb_id = 217594 ON CONFLICT (game_id, language_code) DO NOTHING;
