INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Nikoderiko: The Magical World', 'Join Niko and Luna on their quest in Nikoderiko, a vibrant platform adventure. When the duo discovers an ancient relic on a magical island, the villainous Grimbald of the Cobring Gems Company snatches it away. To save the island and its tribes, they must navigate seven unique worlds with the help of their animal friends and defeat the Cobring army. With family-friendly design, couch co-op, and music by David Wise, Nikoderiko promises a magical, mysterious journey for all ages.' FROM games WHERE igdb_id = 305108 ON CONFLICT (game_id, language_code) DO NOTHING;
