INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Farlands', 'Congratulations, you''ve bought your own planet! An agrarian rock in the edge of the galaxy, which, for some reason, was almost given away for free. So the time has come to leave the hectic and stressful life of the overcrowded metropolis for a more rural and rewarding life.' FROM games WHERE igdb_id = 236859 ON CONFLICT (game_id, language_code) DO NOTHING;
