INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('orebound', 316787, '2024-10-24', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8y3s.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar34n1.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Orebound', 'Journey on a quest to find the Emberstone. Lost in the depths of time. The king has tasked you to find it buried in the mountains. Dig deep and automate mining in the mountains before you. Craft, discover runes, send precious metals and gems back to your kingdom. Grow, mine and find the Emberstone.' FROM games WHERE igdb_id = 316787 ON CONFLICT (game_id, language_code) DO NOTHING;
