INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('alone-in-the-dark--1', 213237, '2024-03-20', 75, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coa1g8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2bwy.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alone in the Dark', 'Alone in the Dark weaves a chilling tapestry of psychological horror and Southern Gothic charm, reimagining the iconic game that set the benchmark for the genre. We invite you to join us on a journey into madness, where each encounter could be your last. With each step you take closer to unravelling Derceto''s mystery, the eyes that watch from the darkness grow hungrier. Every bullet means the difference between survival and an unthinkable end. The next door you unlock could lead to a nightmarish realm offering nothing but slashing claws, grasping tentacles, and frayed sanity. Journey to interbellum Louisiana, where an era of decadence hides a darker tale - of escape from past traumas and an intolerant society, into the waiting grasp of something darker, something that has patiently lurked for impossible eons. This is Alone in the Dark as you''ve never seen it - a skillfully-woven narrative of Southern Gothic elegance and eldritch madness that pays homage to its legendary origins while taking the next step forward in survival horror storytelling.' FROM games WHERE igdb_id = 213237 ON CONFLICT (game_id, language_code) DO NOTHING;
