INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rogue Flight', 'Rogue Flight is a breathtaking arcade space combat game inspired by the landmark style of 80''s and 90''s prestige anime. Traverse the Sol system and join a flight force voiced by a veteran cast, featuring Japanese talent from Sailor Moon, Neon Genesis Evangelion, Gundam, Naruto & One Piece, and English voice talent featured in Overwatch and Fallout 76, League of Legends and Marvel''s Avengers. Jump into true stylish arcade action with a huge host of spacecraft upgrades, game modes and multiple narrative paths.' FROM games WHERE igdb_id = 318086 ON CONFLICT (game_id, language_code) DO NOTHING;
