INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('3-minutes-to-midnight', 86657, '2024-08-22', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2m6b.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4v0.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '3 Minutes to Midnight', '3 Minutes to Midnight is Scarecrow Studio ’s first adventure game with its development led by Jan Serra It is a classic point-and-click adventure game telling the story of Betty Anderson. Do you love unexpected stories and puzzling twists, as well as the feeling of satisfaction that comes when you solve riddles – the harder they are the better? You can’t stop laughing at funny dialogues? You can’t get enough of the "give me more" feeling after you discover the last clue? Then you will love this game! Move around beautifully drawn 2D scenes full of details. Experience a very personal, complex, and interactive story driven by exploration and puzzle-solving. Meet the peculiar characters of this game, and find out about their background stories. Furthermore, there are multiple Easter eggs hidden in the game. Can you spot them all?' FROM games WHERE igdb_id = 86657 ON CONFLICT (game_id, language_code) DO NOTHING;
