INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'World of Jade Dynasty', '"World of Jade Dynasty" (Zhu Xian World) is a fairy-themed online game developed by Perfect World Games. It was launched for public beta on December 19, 2024. The game is developed using the UE5 engine, using various technologies such as physical rasterization and ray tracing rendering, dynamic shadow options, screen space and true 3D reflection.' FROM games WHERE igdb_id = 323920 ON CONFLICT (game_id, language_code) DO NOTHING;
