INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Stray Children', '“The Olders, they come to eat the Children…” All of the adults have become monsters, the rumors say. Nowhere is safe outside these walls. Welcome to Stray Children — a bittersweet, fairy tale RPG, created by many of the same people behind beloved cult-classics like Chulip, Little King’s Story, Rule of Rose, Super Mario RPG, and, of course, Moon: Remix RPG Adventure.' FROM games WHERE igdb_id = 266692 ON CONFLICT (game_id, language_code) DO NOTHING;
