INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Firefighter Connor', 'Firefighter Connor is a linear narrative visual novel that tells a story in a modern world where humans and furries coexist. The player will play the role of Luo Geng, who is 22 year-old, eligible for marriage registration, and somehow ends up with a marriage with a furry firefighter named Connor.' FROM games WHERE igdb_id = 266524 ON CONFLICT (game_id, language_code) DO NOTHING;
