INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bō: Path of the Teal Lotus', 'Bo is a hand-drawn 2D Metroidvania based in a colorful world of Japanese folklore. You play as a tiny fox spirit that grows from lotus blossom after being blessed by the moon god. Use your legendary bō staff to bounce and move fluidly through a delightfully-demonic east asian fever dream. Use the tight movement and reset system to reach areas efficiently and gracefully or recover chaotically while floundering for footing.' FROM games WHERE igdb_id = 154161 ON CONFLICT (game_id, language_code) DO NOTHING;
