INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Operator', 'As an Operator, you will assist FDI''s field agents by analyzing evidence on your computer and making deductions. Help them solve impossible cases in this immersive interface game, full of plot twists and mysteries. Everything will be explained, you just have to ████ ██ ██████.' FROM games WHERE igdb_id = 216958 ON CONFLICT (game_id, language_code) DO NOTHING;
