INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Soulmask', 'Soulmask is a sandbox game that prioritizes an authentic survival experience. As the "last one" blessed with the mysterious mask, players will grapple for survival in a primitive land steeped in mysterious faiths, carving out a path to ascendance. Start from nothing, explore, build, recruit tribesmen to fortify your clan, and ultimately unravel the mysterious truths hidden behind the civilizations of this world.' FROM games WHERE igdb_id = 272600 ON CONFLICT (game_id, language_code) DO NOTHING;
