INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Earth Defense Force: World Brothers 2', 'Earth Defense Force: World Brothers 2 tells the story of what happened to the voxel Earth after the events of the first installment. It cleverly introduces elements from Earth Defense Force 6 and features the Wing Diver Shooter, who didn’t make it into the previous game. This latest installment is filled with more love for the Earth Defense Force series (and Earth!) than ever before!' FROM games WHERE igdb_id = 268010 ON CONFLICT (game_id, language_code) DO NOTHING;
