INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Another Crab''s Treasure', 'Another Crab’s Treasure is a soulslike adventure set in a crumbling underwater world plagued by a mysterious curse. As Kril the hermit crab, you’ll need to wear the trash around you as shells to withstand attacks from enemies many times your size. Embark on an epic treasure hunt to buy back your repossessed shell, and discover the dark secrets behind the polluted ocean.' FROM games WHERE igdb_id = 200903 ON CONFLICT (game_id, language_code) DO NOTHING;
