INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hookah Haze', 'Hookah Haze is a visual novel developed by Acquire and published by Aniplex. The player takes the role of a terminally ill protagonist, whose final wish is to manage a hookah lounge. Through this new job, they meet various patrons and bond with them through hookah. The game has been compared to VA-11 Hall-A and Coffee Talk by critics.' FROM games WHERE igdb_id = 278806 ON CONFLICT (game_id, language_code) DO NOTHING;
