INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Shadow of the Orient', 'Ready to do battle with evil and save the day? Shadow of the Orient is a 2d pixel art action adventure platformer game with fully customizable touch controls, fluid movement and smooth animations. Explore vast levels filled with secrets, quests and loot. Fight your way through hordes of samurai enemies and mythological creatures using your Dao sword or fight off enemies at a distance with ranged weapons.' FROM games WHERE igdb_id = 262898 ON CONFLICT (game_id, language_code) DO NOTHING;
