INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('caves-of-qud', 24054, '2024-12-05', 94, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7eda.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arhva.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Caves of Qud', 'Caves of Qud is a science fantasy roguelike epic steeped in retro-futurism, deep simulation, and swathes of sentient plants. The game weaves a handwritten narrative through rich physical, social, and historical simulations. The result is a hybrid handcrafted & procedurally-generated world where you can do just about anything. Assemble your character from over 70 mutations and defects, and 24 castes and kits - it’s all the character diversity you could want. Explore procedurally-generated regions with some familiar locations - each world is nearly 1 million maps large.' FROM games WHERE igdb_id = 24054 ON CONFLICT (game_id, language_code) DO NOTHING;
