INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('life-is-strange-double-exposure', 305158, '2024-10-29', 82, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8bp9.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar2zk8.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Life is Strange: Double Exposure', 'Max Caulfield, photographer-in-residence at the prestigious Caledon University, discovers her closest new friend Safi dead in the snow. Murdered. To save her, Max tries to Rewind time – a power she’s not used in years… Instead, Max opens the way to a parallel timeline where Safi is still alive and still in danger! Max realizes the killer will soon strike again – in both versions of reality. Only Max can Shift between the two parallel timelines to solve and prevent the same murder.' FROM games WHERE igdb_id = 305158 ON CONFLICT (game_id, language_code) DO NOTHING;
