INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gigantic: Rampage Edition', 'Gigantic: Rampage Edition is a premium and definitive release of the original 5v5 MOBA Hero Shooter, Gigantic, that provides a dynamic and exciting team-based multiplayer experience for fans of both genres. Choose from a diverse roster of unique heroes, each with a set of upgradeable abilities, and team up with four other players to control objectives and take down the opposing team’s mighty Guardian, all while protecting your own. Gigantic: Rampage Edition includes a new game mode, cross platform play, new heroes, new maps, and gameplay improvements that give fans a bigger and more complete GIGANTIC experience than ever before, while welcoming new players to the action and fun-filled world of a Hero Shooter.' FROM games WHERE igdb_id = 288025 ON CONFLICT (game_id, language_code) DO NOTHING;
