INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pixadom', 'Pixadom is a cozy 2D top-down social MMORPG with a charming pixel art style, playable directly in your browser on any modern device. Set in a vibrant world designed for social interaction, Pixadom blends the nostalgia of classic games with a fresh, community-driven experience. Players can enjoy a variety of activities, explore a richly detailed world, and participate in regular events. With a focus on community and creativity, Pixadom offers a unique, engaging multiplayer adventure that evolves through weekly updates and player-driven content.' FROM games WHERE igdb_id = 317582 ON CONFLICT (game_id, language_code) DO NOTHING;
